def even_odd_count(num):
    even_count = 0
    odd_count = 0
    num = abs(num)  # Consider the absolute value for digit analysis

    if num == 0:  # Edge case for 0
        even_count = 1
    else:
        while num > 0:
            digit = num % 10
            if digit % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
            num //= 10  # Remove the last digit

    return (even_count, odd_count)

